test('addHttpMethod does not override an existing method', t => {
  t.plan(4)
  const app = Fastify()

  t.assert.throws(() => { app.addHttpMethod('GET', { hasBody: true }) }, {
    code: 'FST_ERR_ROUTE_METHOD_ALREADY_SUPPORTED',
    message: 'GET method is already supported. Use the "override" option to change it.'
  })
  t.assert.ok(!app.supportedMethods.includes('GET') === false)

  app.addHttpMethod('REBIND', { hasBody: true })
  t.assert.throws(() => { app.addHttpMethod('REBIND') }, {
    code: 'FST_ERR_ROUTE_METHOD_ALREADY_SUPPORTED'
  })

  // adding the same method with the same body support is a no-op
  t.assert.doesNotThrow(() => { app.addHttpMethod('REBIND', { hasBody: true }) })
})

test('addHttpMethod keeps the body support of an existing method', (t, done) => {
  t.plan(3)
  const app = Fastify()

  t.assert.throws(() => { app.addHttpMethod('GET', { hasBody: true }) }, /GET method is already supported/)

  app.route({
    url: '/',
    method: 'GET',
    handler: function (req, reply) {
      reply.send({ body: req.body ?? null })
    }
  })

  app.inject({ method: 'GET', url: '/' }, (err, response) => {
    t.assert.ifError(err)
    t.assert.deepStrictEqual(response.json(), { body: null })
    done()
  })
})

test('addHttpMethod overrides an existing method when override is set', (t, done) => {
  t.plan(3)
  const app = Fastify()

  app.addHttpMethod('GET', { hasBody: true, override: true })
  t.assert.ok(app.supportedMethods.includes('GET'))

  app.route({
    url: '/',
    method: 'GET',
    handler: function (req, reply) {
      reply.send(req.body)
    }
  })

  app.inject({
    method: 'GET',
    url: '/',
    payload: { hello: 'world' }
  }, (err, response) => {
    t.assert.ifError(err)
    t.assert.deepStrictEqual(response.json(), { hello: 'world' })
    done()
  })
})

